INSERT IGNORE INTO posts(category_id,slug,title,excerpt,content,author,status,published_at) VALUES
((SELECT id FROM categories WHERE slug='technology'),'small-models-big-moment','The small models having a very big moment','Why the next phase of AI may be defined by what fits in your pocket.','For years, progress in AI was measured by scale. A new generation of compact models is changing that equation.\n\nThese models can run locally, respond instantly and keep sensitive information on-device.','Maya Chen','published','2026-08-02 09:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'browser-operating-system','The browser is becoming the operating system—again','Local-first web apps make an old prediction feel newly credible.','The browser has spent three decades absorbing the jobs of the operating system. Modern applications now work offline and sync intelligently.','Jon Bell','published','2026-08-01 10:30:00'),
((SELECT id FROM categories WHERE slug='technology'),'passkeys-ready','Passkeys are finally ready for normal people','The password-free future got quieter and substantially less annoying.','Security improvements only work when people can actually use them. Passkeys are finally reaching that threshold.','Nadia Rahman','published','2026-07-30 12:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'quiet-luxury-gadgets','The quiet luxury era of consumer gadgets','Technology that is designed to recede instead of constantly interrupting.','The most interesting new devices are not asking for more attention. This is a response to years of notification fatigue.','Alex Moreno','published','2026-07-28 09:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'four-day-week-data','What the four-day week data actually says','A nuanced picture of productivity and workplace design.','The strongest experiments redesign meetings, decisions and expectations around focused work.','Sara Kim','published','2026-07-24 08:30:00'),
((SELECT id FROM categories WHERE slug='technology'),'open-ai-stack','A practical guide to the open AI stack','The tools and tradeoffs that matter when you own your infrastructure.','Open models offer control, but that control comes with choices across serving, quality and observability.','Maya Chen','published','2026-07-21 11:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'ransomware-economics','Inside the changing economics of ransomware','Why better backups alone cannot solve the incentive problem.','Ransomware groups increasingly operate like businesses. Defenders must address identity, recovery and payment incentives together.','Nadia Rahman','published','2026-07-18 14:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'local-first-future','Local-first software is a bet on user ownership','Apps are rediscovering the value of data that lives with the user.','Local-first architecture combines the responsiveness of desktop software with the collaboration of the cloud.','Jon Bell','published','2026-07-15 10:00:00'),
((SELECT id FROM categories WHERE slug='technology'),'repairable-hardware','Repairable hardware is becoming desirable again','Modularity is moving from policy requirement to product advantage.','Consumers are keeping devices longer and expecting manufacturers to support repairs with parts and documentation.','Alex Moreno','published','2026-07-12 09:15:00'),
((SELECT id FROM categories WHERE slug='technology'),'async-management','The operating manual for asynchronous teams','Documentation, trust and decisions without another meeting.','Async teams succeed when writing is treated as infrastructure rather than administrative overhead.','Sara Kim','draft',NULL),
((SELECT id FROM categories WHERE slug='technology'),'agents-at-work','Where AI agents are actually useful at work','The best deployments are narrower and less magical than the demos.','Reliable agents work inside bounded processes with clear tools, permissions and review points.','Maya Chen','draft',NULL),
((SELECT id FROM categories WHERE slug='technology'),'post-app-internet','What comes after the app-shaped internet','Services are becoming capabilities that appear exactly where needed.','The next interface may be less about opening destinations and more about invoking capabilities in context.','Jon Bell','archived','2026-06-30 08:00:00');
